import csv, io, json, os, sys
from collections import Counter


def nid(s):
    return str(s).strip().lower()


def norm_text(s):
    s = ''.join(c if c.isalnum() else ' ' for c in str(s).casefold())
    return ' '.join(s.split())


def read_batches(cvr):
    files = []
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if os.path.isfile(p) and (name.endswith('.csv') or name.endswith('.jsonl')):
            files.append(p)
    out = []  # (batch, revision, status, records)
    for p in files:
        with open(p, encoding='utf-8-sig', newline='') as f:
            text = f.read()
        recs = []
        if p.endswith('.jsonl'):
            head = None
            for line in text.splitlines():
                if not line.strip():
                    continue
                o = json.loads(line)
                if head is None:
                    head = o
                    continue
                marks = []
                for m in o.get('marks', []):
                    if 'write_in' in m and m['write_in'] is not None:
                        marks.append((int(m['rank']), 'wi', m['write_in']))
                    elif m.get('candidate') is not None:
                        marks.append((int(m['rank']), 'c', m['candidate']))
                recs.append((o['contest'], marks))
        else:
            head = {}
            lines = text.split('\n')
            i = 0
            while i < len(lines):
                l = lines[i].strip()
                if l.startswith('#'):
                    body = l[1:]
                    if ':' in body:
                        k, v = body.split(':', 1)
                        head[k.strip().lower()] = v.strip()
                    i += 1
                elif not l:
                    i += 1
                else:
                    break
            rows = [r for r in csv.reader(io.StringIO('\n'.join(lines[i:]), newline='')) if r]
            if rows:
                cols = [c.strip().lower() for c in rows[0]]
                ci = cols.index('contest')
                rk = {}
                for j, c in enumerate(cols):
                    if c.startswith('rank') and c[4:].isdigit():
                        rk[j] = int(c[4:])
                for r in rows[1:]:
                    marks = []
                    for j, n in rk.items():
                        if j < len(r) and r[j].strip() != '':
                            for part in r[j].split('|'):
                                if part.strip() == '':
                                    continue
                                if part.strip()[:3].lower() == 'wi:':
                                    marks.append((n, 'wi', part.strip()[3:]))
                                else:
                                    marks.append((n, 'c', part))
                    recs.append((r[ci], marks))
        out.append((str(head['batch']), int(str(head['revision']).strip()),
                    str(head.get('status', 'final')).strip().lower(), recs))
    return out


def read_ballot(marks, contest, info):
    maxr, withdrawn, wmap, canon = info
    byrank = {}
    for rank, kind, val in marks:
        if 1 <= rank <= maxr:
            byrank.setdefault(rank, []).append((kind, val))
    seen = set()
    res = []
    for r in range(1, maxr + 1):
        ms = set()
        for kind, val in byrank.get(r, []):
            if kind == 'wi':
                c = wmap.get(norm_text(val))
                if c is not None:
                    ms.add(c)
            else:
                ms.add(nid(val))
        if not ms:
            res.append(('skip',))
            continue
        ms -= withdrawn
        if not ms:
            res.append(('pass',))
            continue
        new = ms - seen
        seen |= ms
        if not new:
            res.append(('skip',))
            continue
        if len(new) == 1:
            res.append(('choice', next(iter(new))))
        else:
            res.append(('over',))
    return tuple(res)


def read_one(ballot, cont):
    n = len(ballot)
    i = 0
    while i < n:
        k = ballot[i]
        if k[0] == 'choice':
            if k[1] in cont:
                return k[1]
        elif k[0] == 'over':
            return None
        elif k[0] == 'skip':
            if i + 1 >= n or ballot[i + 1][0] == 'skip':
                return None
        i += 1
    return None


def count_contest(c, records, ids):
    cands = {}
    for x in c['candidates']:
        cands[nid(x['id'])] = x
    wmap = {}
    withdrawn = set()
    cont = []
    for x in c['candidates']:
        if x.get('status') == 'withdrawn':
            withdrawn.add(nid(x['id']))
        else:
            cont.append(nid(x['id']))
    for w in c.get('write_ins', []):
        for t in [w['name']] + list(w.get('aliases', [])):
            wmap[norm_text(t)] = nid(w['id'])
        cont.append(nid(w['id']))
    written = {}
    for x in c['candidates'] + c.get('write_ins', []):
        written[nid(x['id'])] = x['id']
    lot = {nid(x): i for i, x in enumerate(c.get('lot_order', []))}
    info = (c['max_ranks'], withdrawn, wmap, None)
    sigs = Counter(read_ballot(m, c['id'], info) for m in records)
    total = len(records)
    out = {'contest': c['id'], 'ballots': total, 'winner': None, 'rounds': []}
    continuing = set(cont)
    history = []
    rnd = 0
    while True:
        rnd += 1
        votes = {x: 0 for x in continuing}
        active = 0
        for b, n in sigs.items():
            r = read_one(b, continuing)
            if r is not None:
                votes[r] += n
                active += n
        history.append(votes)
        entry = {'round': rnd, 'tallies': {written[k]: v for k, v in votes.items()},
                 'exhausted': total - active, 'eliminated': []}
        out['rounds'].append(entry)
        if active == 0:
            break
        win = [k for k, v in votes.items() if v * 2 > active]
        if win or len(continuing) == 1:
            out['winner'] = written[win[0] if win else next(iter(continuing))]
            break
        zero = [k for k, v in votes.items() if v == 0]
        if zero:
            elim = zero
        else:
            tied = [k for k, v in votes.items() if v == min(votes.values())]
            j = rnd - 2
            while len(tied) > 1 and j >= 0:
                m = min(history[j][k] for k in tied)
                tied = [k for k in tied if history[j][k] == m]
                j -= 1
            if len(tied) > 1:
                tied = [max(tied, key=lambda k: lot.get(k, -1))]
            elim = tied
        entry['eliminated'] = sorted(written[k] for k in elim)
        continuing -= set(elim)
        if not continuing:
            break
    return out


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, 'election.json'), encoding='utf-8') as f:
        el = json.load(f)
    best = {}
    for b, rev, st, recs in read_batches(os.path.join(inp, 'cvr')):
        if b not in best or rev > best[b][0]:
            best[b] = (rev, st, recs)
    per = {}
    for rev, st, recs in best.values():
        if st == 'void':
            continue
        for cid, marks in recs:
            per.setdefault(cid, []).append(marks)
    res = {'election': el['election'],
           'contests': [count_contest(c, per.get(c['id'], []), None) for c in el['contests']]}
    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


main()
